INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷81·晋少帝本纪·天福七年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0f7599ab625e6aecad46626068a963056a59c78/content/books/zizhi-tongjian/vol-283/year-0942/part-04/sources/library/jiuwudaishi-081-942-xiangzhou/source.txt", "note": "《旧五代史》卷81·晋少帝本纪·天福七年八月，段落 jiu-wudaishi-205deb4a7860-p001980；已核上下文及传主，纸本及异文待核。", "id": "e7df1d68-6118-5aa8-97f6-0303fb83a139"}, {"title": "资治通鉴·卷283·天福七年八月至年末", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0f7599ab625e6aecad46626068a963056a59c78/content/books/zizhi-tongjian/vol-283/year-0942/part-04/sources/library/tongjian-283-942-autumn-winter/source.txt", "note": "《资治通鉴》卷283·天福七年八月至年末，段落 zizhi-tongjian-a63549944a71-p003363；已核上下文及传主，纸本及异文待核。", "id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"title": "新五代史·卷65·南汉世家·钱帛馆之战", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0f7599ab625e6aecad46626068a963056a59c78/content/books/zizhi-tongjian/vol-283/year-0942/part-04/sources/library/xinwudaishi-065-zhang-yuxian-battle/source.txt", "note": "《新五代史》卷65·南汉世家·钱帛馆之战，段落 xin-wudaishi-b08f244b9241-p003279；已核上下文及传主，纸本及异文待核。", "id": "8f5916ed-cd8d-54c4-9694-a8863b6edb56"}, {"title": "新五代史·卷68·闽世家·余廷英", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0f7599ab625e6aecad46626068a963056a59c78/content/books/zizhi-tongjian/vol-283/year-0942/part-04/sources/library/xinwudaishi-068-yu-tingying/source.txt", "note": "《新五代史》卷68·闽世家·余廷英，段落 xin-wudaishi-b08f244b9241-p003409；已核上下文及传主，纸本及异文待核。", "id": "256f4af2-9163-50df-8363-cbf3d366dd88"}, {"title": "资治通鉴·卷283·天福七年五月及随后记载", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/tongjian-283-942-may/source.txt", "note": "《资治通鉴》卷283·天福七年五月及随后记载，段落 zizhi-tongjian-a63549944a71-p003362；已核上下文及传主，纸本及异文待核。", "id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"title": "新五代史·卷9·晋本纪·天福七年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/03f32f35d226d0f16dc68b58596ef35b6835b720/content/books/zizhi-tongjian/vol-283/year-0942/part-03/sources/library/xinwudaishi-009-942-succession/source.txt", "note": "《新五代史》卷9·晋本纪·天福七年，段落 xin-wudaishi-b08f244b9241-p000333；已核上下文及传主，纸本及异文待核。", "id": "ce49f762-1a4b-5f35-8f95-f69e69f10973"}, {"title": "新五代史·卷65·南汉世家·刘龑去世", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/xinwudaishi-065-liu-yan-death/source.txt", "note": "《新五代史》卷65·南汉世家·刘龑去世，段落 xin-wudaishi-b08f244b9241-p003277；已核上下文及传主，纸本及异文待核。", "id": "0d0e70f0-ef89-5444-9ba0-ce63e39af14d"}, {"title": "新五代史·卷68·闽世家·王延羲妻李氏", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/xinwudaishi-068-min-li-empress/source.txt", "note": "《新五代史》卷68·闽世家·王延羲妻李氏，段落 xin-wudaishi-b08f244b9241-p003411；已核上下文及传主，纸本及异文待核。", "id": "f65572e7-91e0-5d18-a84c-68aa6429f9d4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张遇贤", "aliases": ["張遇賢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "博罗县吏。942年循州起事者拥立他为领袖，他称中天八国王、改元永乐并置官。南汉派刘弘昌、刘弘杲征讨，二人在钱帛馆被围，后由将领救出。生卒年未载。", "biography": null, "status": "draft", "id": "508b1255-a234-507d-a64f-ede078d1c559"}, {"name": "刘弘度", "aliases": ["劉弘度", "刘洪度", "劉洪度"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘度，获封王爵之子。", "biography": null, "status": "draft", "id": "9f834996-df40-5434-9360-acbf54bfe3c6"}, {"name": "刘弘昌", "aliases": ["劉弘昌", "刘洪昌", "劉洪昌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘昌，获封王爵之子。", "biography": null, "status": "draft", "id": "fda27388-00bf-5390-90ae-9604e2ec1c33"}, {"name": "刘弘杲", "aliases": ["劉弘杲", "刘洪杲", "劉洪杲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘杲，获封王爵之子。", "biography": null, "status": "draft", "id": "eb7c29f2-2022-5446-97aa-43b3b6d75ad8"}, {"name": "陈道庠", "aliases": ["陳道庠", "陈道痒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉指挥使，端州人。942年钱帛馆之战中救出被围的刘弘昌、刘弘杲。主书前处写陈道痒，同段籍贯句及新五代史写陈道庠，姓名据此校读，原文不改。", "biography": null, "status": "draft", "id": "8c0e66da-c540-5719-8bf2-606db592f4bf"}, {"name": "万景忻", "aliases": ["萬景忻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉将领。《新五代史》记942年与陈道庠在钱帛馆奋战，帮助刘弘昌、刘弘杲突围。生卒年未载。", "biography": null, "status": "draft", "id": "b3501eea-231e-526f-aac3-50b11c0becbb"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "王清", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国军都虞候，曲周人。942年襄州久围未克时劝高行周加紧进攻，并与刘词率军先登。生卒年未载。", "biography": null, "status": "draft", "id": "ba8c58db-075d-59e6-967b-056db790e06a"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "安从进", "aliases": ["安從進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安从进，受询的侍卫都指挥使。", "biography": null, "status": "draft", "id": "3b1f48e5-6ce0-58cd-add7-1bdf9f0d4812"}, {"name": "安宏赞", "aliases": ["安宏贊"], "era": "五代十国", "birth_year": null, "death_year": 942, "description": "安从进的儿子。《旧五代史》942年八月甲子所列高行周奏报称他在襄州被俘后处死。出生年未载；不与之前被俘的安弘义或九月记载的安弘受直接合并。", "biography": null, "status": "draft", "id": "ea8452f6-0a90-5ec4-8248-a30804fd227b"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "赵莹", "aliases": ["趙瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵莹，劝赴任者。", "biography": null, "status": "draft", "id": "1f5a50e7-b046-593f-8be4-621934211b27"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "王继柔", "aliases": ["王繼柔"], "era": "五代十国", "birth_year": null, "death_year": 942, "description": "闽国人物。942年王延羲宴群臣时逼他饮酒，他私下减少酒量，被王延羲与一名客将一同杀死。《通鉴》称他为王延羲从子，《新五代史》列为儿子，亲属异说保留。", "biography": null, "status": "draft", "id": "bf95f829-7525-5f87-a5bf-fc5c80100e69"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "余廷英", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国同平章事，后任泉州刺史。史书记他假称奉诏为后宫选女子而掳人，事发后到福州请罪，又向王延羲及皇后送钱而获准回泉州，后来再次被召为相。生卒年未载。", "biography": null, "status": "draft", "id": "832b139d-4691-56b2-b1c5-6c9d705dbc81"}, {"name": "李氏（王延羲后）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国同平章事李真的女儿，王延羲的妻子。942年被立为皇后。《资治通鉴》和《新五代史》都记她嗜酒，性格强硬。姓名及生卒年未载。", "biography": null, "status": "draft", "id": "eb943b54-1a2c-5d87-8764-6486416880c7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

