SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "《资治通鉴》记博罗县民家出现能说话但不见形体的神的传闻，居民前往占问吉凶，县吏张遇贤恭敬奉事。", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：有神降于博罗县民家，与人言而不见其形，闾阎人往占吉凶，多验，县吏张遇贤事之甚谨。；核对说明：多验是史载民间占问描述，不声称神或预言已得到客观验证。", "status": "draft", "id": "5d0295ef-b79b-5a97-a7d6-9a33d5239566", "subject_id": "4a4394fa-7698-5e8d-86d8-bcdacc09339e", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "张遇贤起事以前，具体年月未载", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：有神降于博罗县民家，与人言而不见其形，闾阎人往占吉凶，多验，县吏张遇贤事之甚谨。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "05e0271f-11de-5586-a391-d78cf021fbae", "subject_id": "4a4394fa-7698-5e8d-86d8-bcdacc09339e", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "person", "field_path": "description", "claim_text": "张遇贤：以县吏身份奉事传闻中的神。", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：有神降于博罗县民家，与人言而不见其形，闾阎人往占吉凶，多验，县吏张遇贤事之甚谨。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "9dba1615-5783-5a5e-862a-5e1d30642a84", "subject_id": "508b1255-a234-507d-a64f-ede078d1c559", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张遇贤：以县吏身份奉事传闻中的神。", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：有神降于博罗县民家，与人言而不见其形，闾阎人往占吉凶，多验，县吏张遇贤事之甚谨。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "3496e2e9-304c-54d2-a5e9-94c72413f3b3", "subject_id": "c8bb18dc-033f-5fec-80de-7d833a54ac0e", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "event", "field_path": "description", "claim_text": "循州各股起事者未有统一领袖，共同祷告后，传称神让张遇贤作首领，于是拥立张遇贤。他称中天八国王，改元永乐，设置官员。", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：时循州盗贼群起，莫相统一，贼帅共祷于神，神大言曰：“张遇贤当为汝主。”于是群帅共奉遇贤，称中天八国王，改元永乐，置百官，；核对说明：神言是记载中的传闻及拥立叙事，不当作客观神命；原文盗贼称谓保留，说明使用起事者。", "status": "draft", "id": "24480603-b2ae-535b-a287-82163d3a7f71", "subject_id": "d44f69ea-c0cd-5e27-be8a-0f3025b418f7", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "942年七月条下，具体起事日期未载", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：时循州盗贼群起，莫相统一，贼帅共祷于神，神大言曰：“张遇贤当为汝主。”于是群帅共奉遇贤，称中天八国王，改元永乐，置百官，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "34b7bd2d-4564-5d3f-a66e-bbeec44532c4", "subject_id": "d44f69ea-c0cd-5e27-be8a-0f3025b418f7", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张遇贤：被拥立后称王、改元并置官。", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：时循州盗贼群起，莫相统一，贼帅共祷于神，神大言曰：“张遇贤当为汝主。”于是群帅共奉遇贤，称中天八国王，改元永乐，置百官，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "cbc4fe10-64a1-5425-88f2-ee8a5f3bcbb7", "subject_id": "2fd19b66-bc07-5e6f-8071-3cf6d8915720", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "event", "field_path": "description", "claim_text": "张遇贤部众攻掠海滨地区，由诸将指示进退。", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：攻掠海隅。遇贤年少，无他方略，诸将但告进退而已。；核对说明：无他方略为史书评价，不补军事能力测试或各城陷落日期。", "status": "draft", "id": "f0a80ddb-ca49-52ae-a473-6bad9bff9f6c", "subject_id": "00d5e3c1-9573-57c2-bc1e-b4c7aa3d8965", "source_id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "942年起事后，具体日期未载", "citation": "卷283·后晋天福七年（942；七月至八月条下及追述）·zztj-v283-y0942-p027·原文件第32行", "note": "原文：攻掠海隅。遇贤年少，无他方略，诸将但告进退而已。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "814af33d-b9d3-507f-81a3-02b5d70fa5da", 